#!/usr/bin/env node
// MIT — Original SF88 event-feed subscriber commands.
import { resolve, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createSubscription, openSubscription } from './subscriber.mjs';
import { safeCode } from '../node/store.mjs';

const help = [
  'Starforge event-feed buyer',
  '',
  'init --dir DIR --config ORIGINAL_BUYER_JSON --feed FEED [--id NAME]',
  '     [--page-size 100] [--runtime SF88_DIR] [--buyer-state DIR]',
  '     [--cursor CURSOR --after-sequence N]',
  'sync --dir DIR [--max-pages N]',
  'recover --dir DIR',
  'inspect --dir DIR [--limit N]',
  'export --dir DIR --out EVENTS.ndjson',
  'workspace --dir DIR [--port 0]',
  '',
  'sync collects one fixed sequence window through the original buyer.',
  'Another sync collects events received since the last completed window.',
  'recover reads the same recorded operation and retained response.',
  'export writes an immutable NDJSON file and its matching manifest.',
  'The existing operator policy, signer and payment journal govern each page.'
].join('\n');

function options(args,allowed) {
  const selected={};
  for(let i=0;i<args.length;i+=2) {
    const key=args[i],value=args[i+1];
    if(!allowed.includes(key)||Object.hasOwn(selected,key)||!value||value.startsWith('--'))
      throw Object.assign(new Error('Invalid option'),{code:'FEED_CLI_OPTION_INVALID'});
    selected[key]=value;
  }
  return selected;
}
function number(value,fallback) {
  if(value===undefined)return fallback;
  if(!/^(0|[1-9][0-9]*)$/.test(value)||!Number.isSafeInteger(Number(value)))
    throw Object.assign(new Error('Invalid number'),{code:'FEED_CLI_NUMBER_INVALID'});
  return Number(value);
}
function required(value) {
  if(!value)throw Object.assign(new Error('Required option missing'),{code:'FEED_CLI_OPTION_REQUIRED'});
  return value;
}
export async function main(args=process.argv.slice(2)) {
  const [command,...rest]=args;
  if(!command||command==='--help'||command==='help'||rest.includes('--help')) {
    process.stdout.write(help+'\n'); return;
  }
  const allowed={
    init:['--dir','--config','--feed','--id','--page-size','--runtime','--buyer-state','--cursor','--after-sequence'],
    sync:['--dir','--max-pages'],recover:['--dir'],inspect:['--dir','--limit'],
    export:['--dir','--out'],workspace:['--dir','--port']
  };
  if(!allowed[command])throw Object.assign(new Error('Unknown command'),{code:'FEED_CLI_COMMAND_INVALID'});
  const selected=options(rest,allowed[command]);
  const directory=resolve(required(selected['--dir']));
  if(command==='workspace') {
    const {serveWorkspace}=await import('./workspace.mjs');
    const service=await serveWorkspace({directory,port:number(selected['--port'],0)});
    process.stdout.write(JSON.stringify({url:service.url,directory})+'\n');
    const stop=()=>service.close().catch(()=>{process.exitCode=1;});
    process.once('SIGINT',stop);process.once('SIGTERM',stop);
    return;
  }
  let subscription;
  const controller=new AbortController();
  const stop=()=>controller.abort();
  process.once('SIGINT',stop);process.once('SIGTERM',stop);
  try {
    subscription=command==='init'
      ? await createSubscription({directory,config:resolve(required(selected['--config'])),
          runtimeDirectory:resolve(selected['--runtime']??fileURLToPath(new URL('../',import.meta.url))),
          buyerStateDirectory:resolve(selected['--buyer-state']??join(directory,'original-buyer')),
          id:selected['--id']??required(selected['--feed']),feedId:required(selected['--feed']),
          pageSize:number(selected['--page-size'],100),startCursor:selected['--cursor']??null,
          afterSequence:number(selected['--after-sequence'],0)})
      :await openSubscription(directory);
    const result=command==='sync'
      ?await subscription.collect({signal:controller.signal,maxPages:number(selected['--max-pages'],Number.MAX_SAFE_INTEGER)})
      :command==='recover'?await subscription.recover({signal:controller.signal})
      :command==='export'?await subscription.exportEvents(resolve(required(selected['--out'])))
      :subscription.inspect({limit:number(selected['--limit'],20)});
    process.stdout.write(JSON.stringify(result,null,2)+'\n');
    if(command==='sync'&&!['CAUGHT_UP','PAGE_LIMIT_REACHED'].includes(result.state))process.exitCode=2;
  } finally {
    process.removeListener('SIGINT',stop);process.removeListener('SIGTERM',stop);
    subscription?.close();
  }
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url))
  main().catch(error=>{
    process.stderr.write(JSON.stringify({error:safeCode(error?.code,'EVENT_FEED_COMMAND_FAILED')})+'\n');
    process.exitCode=1;
  });

// MIT. Offline source/cache handoff inside the existing retained runtime workspace.
import { readdir, lstat } from 'node:fs/promises';
import { join, basename } from 'node:path';
import { reviewRuntimeTransfer, exportRuntimeTransfer, inspectRuntimeTransfer, beginRuntimeTransferReceive,
  receiveRuntimeTransferPart, completeRuntimeTransferReceive, openRuntimeTransferDownload,
  installReceivedRuntime } from '../runtime-transfer.mjs';
import { MAX_MANIFEST_BYTES, MAX_PART_BYTES } from '../runtime-transfer-lock.mjs';
import { plain, now, digest, canonical, json, need, absolute, recordId, operationId,
  privateDirectory, makePrivate, readJSON, saveJSON, operationLease, operationRunning } from './storage.mjs';

export const transferOperationFields = {
  'transfer-export': ['runtimeId', 'label', 'cache', 'offline', 'lockSha256', 'partBytes'],
  'transfer-complete': ['cacheTransferId', 'populateCache'],
  'transfer-install': ['cacheTransferId', 'name', 'nodeHeaders', 'install'],
  'transfer-recover': ['cacheTransferId', 'runtimeId', 'name', 'nodeHeaders', 'install'],
};
const base = root => join(root, 'runtime-transfers');
const metadata = (root, id) => join(base(root), 'records', recordId(id) + '.json');
async function ensure(path) {
  try { return await makePrivate(path); }
  catch (error) { if (error.code !== 'EEXIST') throw error; return privateDirectory(path); }
}
export async function initializeTransferWorkspace(root) {
  await ensure(base(root));
  await ensure(join(base(root), 'records'));
  await ensure(join(base(root), 'cohorts'));
}
async function entry(root, id) {
  const item = await readJSON(metadata(root, id));
  need(item?.id === id && typeof item.directory === 'string', 'RUNTIME_TRANSFER_ENTRY_INVALID');
  absolute(item.directory);
  return item;
}
async function retain(root, directory, label, extra = {}) {
  absolute(directory);
  need(typeof label === 'string' && label.trim() && label.length <= 120, 'RUNTIME_TRANSFER_LABEL_INVALID');
  const id = digest(directory).slice(0, 24), path = metadata(root, id), existing = await readJSON(path, true);
  if (existing) {
    need(existing.directory === directory, 'RUNTIME_TRANSFER_ENTRY_COLLISION'); return existing;
  }
  const item = { id, directory, label: label.trim(), createdAt: now(), ...extra };
  try { await saveJSON(path, item); } catch (error) { if (error.code !== 'EEXIST') throw error; }
  return entry(root, id);
}
function summary(item, view) {
  return { ...item, mode: view.state?.mode ?? item.mode, phase: view.state?.phase ?? 'PREPARING',
    runtime: view.manifest?.runtime ?? view.state?.runtime ?? null,
    transferId: view.manifest?.transferId ?? null, manifestSha256: view.manifestSha256,
    complete: view.complete, partCount: view.parts?.length ?? 0,
    missingPartCount: view.missingParts?.length ?? 0, invalidPartCount: view.invalidParts?.length ?? 0,
    packageCount: view.manifest?.artifacts.length ?? view.state?.totalPackages ?? 0,
    payloadBytes: view.manifest?.payload.bytes ?? null,
    error: view.state?.error ?? null, progress: {
      completedPackages: view.state?.completedPackages ?? null, totalPackages: view.state?.totalPackages ?? null,
      cachedArtifacts: view.state?.cachedArtifacts?.length ?? null },
    cacheDirectory: view.cacheDirectory ?? null, filesDirectory: view.filesDirectory ?? null };
}
export async function runtimeTransferWorkspaceState(root, { cacheTransferId = null } = {}) {
  await initializeTransferWorkspace(root);
  const ids = (await readdir(join(base(root), 'records'))).filter(name => /^[a-f0-9]{24}\.json$/.test(name));
  const transfers = [];
  for (const name of ids) {
    const item = await readJSON(join(base(root), 'records', name));
    try { transfers.push(summary(item, await inspectRuntimeTransfer({ directory: item.directory }))); }
    catch (error) { transfers.push({ ...item, phase: error.code === 'ENOENT' ? 'PREPARING' : 'UNAVAILABLE',
      error: { code: error.code ?? 'RUNTIME_TRANSFER_INSPECTION_FAILED' } }); }
  }
  transfers.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  const selected = cacheTransferId ? await entry(root, recordId(cacheTransferId)) : null;
  let inspected = null;
  if (selected) {
    try { inspected = { ...selected, ...await inspectRuntimeTransfer({ directory: selected.directory }) }; }
    catch (error) { inspected = { ...selected, state: { mode: selected.mode, phase: error.code === 'ENOENT' ? 'PREPARING' : 'UNAVAILABLE' },
      complete: false, manifest: null, parts: [], error: { code: error.code ?? 'RUNTIME_TRANSFER_INSPECTION_FAILED' } }; }
  }
  return { transfers, selected: inspected, maximumPartBytes: MAX_PART_BYTES, maximumManifestBytes: MAX_MANIFEST_BYTES };
}
export async function reviewWorkspaceRuntimeTransfer(root, { runtimeId, runtimeDirectory } = {}) {
  recordId(runtimeId);
  return { runtimeId, ...await reviewRuntimeTransfer({ runtimeDirectory: absolute(runtimeDirectory) }) };
}
export async function attachWorkspaceRuntimeTransfer(root, { directory, label } = {}) {
  await initializeTransferWorkspace(root);
  const path = await privateDirectory(absolute(directory));
  const view = await inspectRuntimeTransfer({ directory: path, verify: true });
  const item = await retain(root, path, label ?? basename(path), { mode: view.state.mode });
  return { cacheTransferId: item.id, transfer: summary(item, view), reopened: true };
}
export async function prepareWorkspaceRuntimeTransferReceive(root, { manifest, manifestSha256, requestId, label } = {}) {
  await initializeTransferWorkspace(root); operationId(requestId);
  need(label === undefined || typeof label === 'string' && label.trim() && label.length <= 120, 'RUNTIME_TRANSFER_LABEL_INVALID');
  need(typeof manifest === 'string' && Buffer.byteLength(manifest) <= MAX_MANIFEST_BYTES, 'RUNTIME_TRANSFER_MANIFEST_LIMIT');
  const directory = join(base(root), 'cohorts', requestId);
  const view = await beginRuntimeTransferReceive({ directory, manifest, manifestSha256 });
  const item = await retain(root, directory, label ?? view.manifest.runtime.packageVersion, { mode: 'RECEIVE', requestId });
  return { cacheTransferId: item.id, transfer: summary(item, view), inspection: view };
}
export async function uploadWorkspaceRuntimeTransferPart(root, { cacheTransferId, index, body } = {}) {
  const selected = await entry(root, recordId(cacheTransferId));
  return receiveRuntimeTransferPart({ directory: selected.directory, index, body });
}
export async function downloadWorkspaceRuntimeTransfer(root, { cacheTransferId, kind, index } = {}) {
  const selected = await entry(root, recordId(cacheTransferId));
  return openRuntimeTransferDownload({ directory: selected.directory, kind, index });
}
async function activeLock(path) {
  try { if (!(await lstat(path)).isFile()) return false; }
  catch (error) { if (error.code === 'ENOENT') return false; throw error; }
  return operationRunning(path);
}
export async function normalizeRuntimeTransferOperation(root, request, id, config) {
  await initializeTransferWorkspace(root);
  need(Object.hasOwn(transferOperationFields, request.operation), 'RUNTIME_TRANSFER_OPERATION_INVALID');
  if (request.populateCache !== undefined) need(typeof request.populateCache === 'boolean', 'RUNTIME_TRANSFER_OPTIONS_INVALID');
  if (request.operation === 'transfer-export') {
    need(request.runtimeDirectory && typeof request.cache === 'string' &&
      /^[a-f0-9]{64}$/.test(request.lockSha256 ?? ''), 'RUNTIME_TRANSFER_REVIEW_REQUIRED');
    need(request.offline === undefined || typeof request.offline === 'boolean', 'RUNTIME_TRANSFER_OPTIONS_INVALID');
    need(request.partBytes === undefined || Number.isInteger(request.partBytes) &&
      request.partBytes >= 65536 && request.partBytes <= MAX_PART_BYTES, 'RUNTIME_TRANSFER_PART_LIMIT');
    request.offline ??= true;
    request.transferDirectory = join(base(root), 'cohorts', id);
    const item = await retain(root, request.transferDirectory, request.label ?? 'Offline runtime transfer',
      { mode: 'EXPORT', runtimeId: request.runtimeId });
    request.cacheTransferId = item.id;
  } else {
    const selected = await entry(root, recordId(request.cacheTransferId));
    request.transferDirectory = selected.directory;
    const view = await inspectRuntimeTransfer({ directory: selected.directory });
    need(view.state.mode === 'RECEIVE', 'RUNTIME_TRANSFER_RECEIVER_REQUIRED');
    request.manifestSha256 = view.manifestSha256;
    if (['transfer-install', 'transfer-recover'].includes(request.operation)) {
      need(typeof request.name === 'string' && /^[a-zA-Z0-9][a-zA-Z0-9._-]{0,79}$/.test(request.name),
        'RUNTIME_WORKSPACE_NAME_INVALID');
      request.targetDirectory = join(config.runtimeHome, request.name);
      request.targetId = digest(request.targetDirectory).slice(0, 24);
      if (request.operation === 'transfer-recover')
        need(request.runtimeDirectory, 'RUNTIME_TRANSFER_RECOVERY_RUNTIME_REQUIRED');
    }
  }
  const names = (await readdir(join(root, 'operations'))).filter(name => /^[a-f0-9-]{36}$/.test(name));
  for (const oldId of names) {
    if (oldId === id) continue;
    const directory = join(root, 'operations', oldId), old = await readJSON(join(directory, 'request.json'), true);
    if (old?.cacheTransferId !== request.cacheTransferId) continue;
    const state = await readJSON(join(directory, 'state.json'), true);
    need(state?.phase !== 'QUEUED' && !(state?.phase === 'RUNNING' && await activeLock(join(directory, 'worker.lock'))),
      'RUNTIME_TRANSFER_OPERATION_RUNNING', 'Open the retained transfer operation before another change', 409);
  }
  return request;
}
export async function executeRuntimeTransferOperation(root, request, { checkpoint = async () => {} } = {}) {
  const selected = await entry(root, recordId(request.cacheTransferId));
  need(selected.directory === request.transferDirectory, 'RUNTIME_TRANSFER_ENTRY_CHANGED');
  const onProgress = transferProgress => checkpoint({ transferProgress });
  let result;
  if (request.operation === 'transfer-export') result = await exportRuntimeTransfer({
    runtimeDirectory: request.runtimeDirectory, directory: selected.directory, cache: request.cache,
    offline: request.offline, expectedLockSha256: request.lockSha256,
    ...(request.partBytes ? { partBytes: request.partBytes } : {}), onProgress,
  });
  else {
    const view = await inspectRuntimeTransfer({ directory: selected.directory });
    need(view.manifestSha256 === request.manifestSha256, 'RUNTIME_TRANSFER_REVIEW_CHANGED');
    if (request.operation === 'transfer-complete') result = await completeRuntimeTransferReceive({
      directory: selected.directory, populateCache: request.populateCache ?? true, onProgress,
    });
    else {
      result = await installReceivedRuntime({ directory: selected.directory, runtimeDirectory: request.targetDirectory,
        nodeHeaders: request.nodeHeaders ?? null, install: request.install ?? true,
        recoverFrom: request.operation === 'transfer-recover' ? request.runtimeDirectory : null, onProgress });
      return { cacheTransferId: selected.id, runtimeId: request.targetId, status: result.status,
        transferId: result.transferId, manifestSha256: result.manifestSha256, runtimeDirectory: result.runtimeDirectory };
    }
  }
  return { cacheTransferId: selected.id, ...summary(selected, result) };
}
/** Requeue only this adapter's retained resumable operation, under the original kernel lease. */
export async function recoverWorkspaceRuntimeTransferOperation(root, id) {
  operationId(id);
  const directory = join(root, 'operations', id), request = await readJSON(join(directory, 'request.json'));
  need(Object.hasOwn(transferOperationFields, request.operation), 'RUNTIME_TRANSFER_OPERATION_INVALID');
  if (await activeLock(join(directory, 'worker.lock')) ||
    await activeLock(join(request.transferDirectory, 'transfer.lock')) ||
    request.targetDirectory && await activeLock(join(request.targetDirectory, 'install.lock')))
    return { operationId: id, active: true, resume: false };
  const lease = await operationLease(join(directory, 'worker.lock'));
  try {
    const state = await readJSON(join(directory, 'state.json'));
    if (state.phase === 'SUCCEEDED') return { operationId: id, completed: true, resume: false };
    need(['QUEUED', 'RUNNING', 'FAILED'].includes(state.phase), 'RUNTIME_TRANSFER_OPERATION_STATE_INVALID');
    await saveJSON(join(directory, 'state.json'), { phase: 'QUEUED', attempt: (state.attempt ?? 0) + 1,
      previousPhase: state.phase, previousError: state.error ?? null, resumedAt: now(), updatedAt: now() }, true);
    return { operationId: id, resume: true };
  } finally { await lease.close(); }
}

export type NativeId = string;
export type Sha256 = string;
export type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export type NativeDocument = Record<string, any>;
export interface CallOptions { requestSignal?: AbortSignal; timeoutMs?: number; }
export interface FileOptions { expectedSha256?: Sha256; chunkBytes?: number; signal?: AbortSignal; }
export interface InputFile { source: string; name: string; sha256?: Sha256; bytes?: number; }
export interface ReviewedInputFile extends InputFile { sha256: Sha256; bytes: number; }
export interface DateMapping {
  format: 'ISO_UTC' | 'UTC_SECONDS' | 'UTC_DATE' | 'ZONE_SECONDS' | 'ZONE_DATE';
  timeZone: string;
  precision?: 'day' | 'second' | 'millisecond';
}
export type ColumnRole = 'date' | 'cryptoId' | 'type' | 'amountOne' | 'amountOneType' |
  'amountTwo' | 'amountTwoType' | 'transactionHash' | 'connectionId' | 'note' | 'ledgerId' | 'rowId';
export type Columns = Partial<Record<ColumnRole, string>>;
export interface ActorRequest { id?: NativeId; name: string; actor: string; createdAt?: string; }
export interface ProfileRequest extends ActorRequest {
  previousProfileId?: NativeId | null;
  file: InputFile;
  delimiter?: ',' | ';' | '\t';
  columns: Columns;
  constants: Record<string, string>;
  target: { entityId: string; entityName?: string; connectionId: string; connectionName?: string; merchantAccount: string };
  date: DateMapping;
  assets: Array<{ network: 'stellar:testnet' | 'stellar:pubnet'; assetDigest: Sha256; cryptoId: string; amountType: string; scale: number }>;
}
export interface PlanRequest extends ActorRequest {
  profileId: NativeId;
  handoffId: NativeId;
  accountantRevisionId: NativeId | 'initial';
  previousPlanId?: NativeId | null;
  decisions?: Array<{ movementId: Sha256; selectionId?: Sha256 | null; action: 'INCLUDE' | 'EXCLUDE' | 'ALREADY_IMPORTED'; reason?: string; reference?: string }>;
  dateEvidence?: Array<{ movementId: Sha256; transferAt: string; note: string; file: InputFile }>;
}
export interface NativeImport {
  id: string;
  entityId: string;
  connectionId: string;
  receivedAt: string;
  reference: string;
  note?: string;
}
export interface CaptureRequest extends ActorRequest {
  purpose: 'IMPORT_RETURN' | 'BASELINE';
  file: InputFile;
  nativeImport: NativeImport;
  layout: { kind: 'INPUT_FORMAT' | 'MAPPED_EXPORT'; delimiter?: ',' | ';' | '\t'; columns?: Columns; date?: DateMapping;
    amountConvention?: 'UNSIGNED' | 'SEND_NEGATIVE'; amountTwoConvention?: 'UNSIGNED' | 'SEND_NEGATIVE'; groupSeparator?: '' | ',' };
}
export interface ReturnRequest extends ActorRequest {
  captureId: NativeId;
  status: 'REVIEWED' | 'BOOKED';
  bookRef?: string;
  accountCode?: string | null;
  note?: string;
  expectedParentId: NativeId | null;
}
export interface RequestMap { profile: ProfileRequest; plan: PlanRequest; capture: CaptureRequest; return: ReturnRequest; }
export type OperationKind = keyof RequestMap;
export interface PageQuery { offset?: number; limit?: number; search?: string; status?: string; }
export interface WorkspaceResult { workspaceId: Sha256; revision: number; }
export interface RecordPage extends WorkspaceResult {
  page: { view: string; items: NativeDocument[]; total: number; offset: number; limit: number; nextOffset: number | null };
}
export interface RowPage extends WorkspaceResult { items: NativeDocument[]; totalRows: number; offset: number; limit: number; }
export interface NativeRecord {
  id: NativeId;
  requestSha256: Sha256;
  previewSha256?: Sha256;
  integrity?: { sha256: Sha256 };
  status?: 'PREPARED' | 'COMMITTED' | 'SUPERSEDED';
  [key: string]: unknown;
}
export interface Preview<K extends OperationKind = OperationKind> extends WorkspaceResult {
  kind: K;
  planId?: NativeId;
  request: RequestMap[K] & { id: NativeId; createdAt: string };
  workspaceRevision: number;
  previewSha256: Sha256;
  requestSha256: Sha256;
  wireSha256: Sha256;
  profile?: NativeDocument;
  plan?: NativeDocument;
  comparison?: NativeDocument;
  summary?: NativeDocument;
  accountantPreview?: NativeDocument;
  items?: NativeDocument[];
  totalRows?: number;
  offset?: number;
  limit?: number;
}
export interface SaveArguments<K extends OperationKind = OperationKind> {
  workspaceId: Sha256;
  planId?: NativeId;
  request: RequestMap[K] & { id: NativeId; createdAt: string; revision: number; previewSha256: Sha256 };
}
export interface SaveResult extends Partial<WorkspaceResult> {
  found: boolean;
  unresolved?: boolean;
  superseded?: boolean;
  recovered?: boolean;
  record?: NativeRecord;
  kind?: OperationKind;
  duplicate?: boolean;
  [key: string]: unknown;
}
export interface RollbackArguments {
  workspaceId: Sha256;
  planId: NativeId;
  request: { id: NativeId; captureId: NativeId; nativeImportId: string; completedAt: string; actor: string; reason: string; reference: string; revision: number };
}
export interface PacketInspection extends WorkspaceResult {
  schema: 'stellar-forge.cryptoworth-receiving-packet.v1';
  planId: NativeId;
  profileId: NativeId;
  sha256: Sha256;
  packetSha256: Sha256;
  name: string;
  bytes: number;
  file: ReviewedInputFile;
  summary: NativeDocument;
  plan: NativeDocument;
  profile: NativeDocument;
  existing: { planId: NativeId | null; received: boolean };
}
export interface PacketOptions { actor: string; name?: string; revision?: number; }
export interface PacketArguments {
  workspaceId: Sha256;
  file: ReviewedInputFile;
  revision: number;
  actor: string;
  name: string;
  expectedSha256: Sha256;
  expectedPacketSha256: Sha256;
}
export type FileSelection =
  { kind: 'cryptoworth'; profileId: NativeId; file: string } |
  { kind: 'cryptoworth'; planId: NativeId; file: string; captureId?: NativeId; returnId?: NativeId; rollbackId?: NativeId; scope?: 'stage' | 'completed' };
export interface FileChunk {
  readId: string;
  file: { name: string; bytes: number; sha256: Sha256; [key: string]: unknown };
  bytes: Uint8Array;
  offset: number;
  complete: boolean;
  nextOffset: number | null;
  [key: string]: unknown;
}
export interface ConnectionOptions {
  url: string;
  workspace: string;
  tokenEnv?: string;
  environment?: Record<string, string | undefined>;
  [key: string]: unknown;
}
export interface AccountingCryptoworthClient {
  readonly workspace: string;
  readonly endpoint?: string;
  open(options?: CallOptions): Promise<NativeDocument>;
  status(args?: { view?: 'summary' | 'profiles' | 'plans' | 'handoffs' | 'rollbacks'; offset?: number; limit?: number }, options?: CallOptions): Promise<NativeDocument>;
  sources(options?: CallOptions): Promise<NativeDocument>;
  source(args: PageQuery & { handoffId: NativeId; accountantRevisionId: NativeId | 'initial' }, options?: CallOptions): Promise<RowPage>;
  template(args: { file: InputFile; delimiter?: ',' | ';' | '\t' }, options?: CallOptions): Promise<WorkspaceResult & { file: ReviewedInputFile; template: NativeDocument; requiredRoles: string[]; suggestedColumns: Columns }>;
  profile(profileId: NativeId, options?: CallOptions): Promise<WorkspaceResult & { record: NativeRecord; profile: NativeDocument; files: NativeDocument[] }>;
  plan(planId: NativeId, args?: { view?: 'summary' | 'captures' | 'returns' | 'rollbacks' | 'files' | 'receivedPackets' | 'decisions' | 'dateEvidence'; offset?: number; limit?: number }, options?: CallOptions): Promise<NativeDocument>;
  rows(planId: NativeId, args?: PageQuery & { captureId?: NativeId }, options?: CallOptions): Promise<RowPage>;
  capture(planId: NativeId, captureId: NativeId, options?: CallOptions): Promise<WorkspaceResult & { record: NativeRecord; comparison: NativeDocument; files: NativeDocument[]; rollbacks: NativeDocument[] }>;
  returned(planId: NativeId, returnId: NativeId, options?: CallOptions): Promise<WorkspaceResult & { record: NativeRecord; files: NativeDocument[] }>;
  rollbackRecord(rollbackId: NativeId, options?: CallOptions): Promise<WorkspaceResult & { record: NativeRecord }>;
  allStatus(view: 'profiles' | 'plans' | 'handoffs' | 'rollbacks', options?: CallOptions): Promise<WorkspaceResult & { items: NativeDocument[]; total: number }>;
  allPlan(planId: NativeId, view: 'captures' | 'returns' | 'rollbacks' | 'files' | 'receivedPackets' | 'decisions' | 'dateEvidence', options?: CallOptions): Promise<WorkspaceResult & { items: NativeDocument[]; total: number }>;
  allRows(planId: NativeId, args?: PageQuery & { captureId?: NativeId }, options?: CallOptions): Promise<WorkspaceResult & { items: NativeDocument[]; total: number }>;
  preview<K extends OperationKind>(kind: K, request: RequestMap[K], selection?: PageQuery & { planId?: NativeId }, options?: CallOptions): Promise<Preview<K>>;
