export async function coingeckoStartup(request, text, operationDirectory) {
  if (request.command !== 'coingecko' || request.args?.[0] !== 'serve' ||
    typeof text !== 'string' || Buffer.byteLength(text) > 65536 || !text.startsWith('{')) return null;
