   const chunk=Buffer.from(part);bytes+=chunk.length;
   need(bytes<=member.bytes,'API_MERCHANT_EXPORT_LENGTH_CHANGED',409);hash.update(chunk);
   let offset=0;
   while(offset<chunk.length){
