  need(body&&typeof body==='object'&&!Array.isArray(body),'API_MERCHANT_JSON_OBJECT_REQUIRED');
  if(command==='act'){
   need(typeof action==='string'&&/^[a-z_]{1,40}$/.test(action),'API_MERCHANT_ACTION_REQUIRED');
