.operator-approval .approval-facts { display: grid; grid-template-columns: minmax(105px, 165px) minmax(0, 1fr); gap: 8px 14px; margin: 0 0 16px; font: 400 12px/1.55 ui-sans-serif, system-ui, sans-serif; }
