.operator-approval details { border-top: 1px solid #d6d6d6; margin: 12px 0 16px; padding-top: 10px; }
.operator-approval summary { cursor: pointer; color: #333; font: 550 12px/1.6 ui-sans-serif, system-ui, sans-serif; }
.operator-approval details[open] summary { margin-bottom: 11px; }
.operator-approval pre { margin: 0; padding: 11px; border: 1px solid #d7d7d7; background: #fff; max-height: 320px; overflow: auto; font: 400 12px/1.6 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; white-space: pre-wrap; overflow-wrap: anywhere; direction: ltr; unicode-bidi: plaintext; }
