}
function editionLabel(record) {
  return (record.dataset?.name || 'Dataset') + ' · ' + record.row_count + ' rows · ' + record.version_id.slice(0, 12);
}
function remember(values) {
  for (const value of values) editions.set(value.version_id, value);
