class AnonymousHeadersMiddleware:
    """Forward public requests without caller cookies or identity credentials."""

    def __init__(self, app: ASGIApp) -> None:
        self.app = app

    async def __call__(
        self, scope: Scope, receive: Receive, send: Send
    ) -> None:
        if scope["type"] == "http":
            scope = dict(scope)
            scope["headers"] = [
                (key, value)
                for key, value in scope.get("headers", ())
                if key.lower() not in {
                    b"authorization", b"cookie", b"proxy-authorization"
                }
            ]
